using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.UI;using Mojinloop.Combat;
namespace Mojinloop.Gameplay { public sealed class GameFlowController:MonoBehaviour { [SerializeField] InputActivityState activity;[SerializeField] CombatController combat;[SerializeField] BackgroundScroller background;[SerializeField] HeroAnimationController animationController;[SerializeField] Text coinText,inputText,pauseText;bool paused;void Start(){combat.CoinsChanged+=UpdateCoins;UpdateCoins(combat.Coins);}void OnDestroy(){if(combat!=null)combat.CoinsChanged-=UpdateCoins;}void Update(){if(Keyboard.current?.f10Key.wasPressedThisFrame==true){paused=!paused;activity.SetPaused(paused);}bool active=activity.IsInputActive&&!paused;background.Scrolling=active;combat.Tick(active,paused);animationController.Apply(FindAnyObjectByType<HeroController>().State);if(inputText!=null)inputText.text=active?"INPUT ACTIVE":"IDLE";if(pauseText!=null)pauseText.text=paused?"PAUSED (F10)":"";}void UpdateCoins(int value){if(coinText!=null)coinText.text=$"COIN {value}";} } }
